import React, {useEffect, useState} from 'react';
import {createRoot} from 'react-dom/client';
import './style.css';

type Role='admin'|'service'|'kitchen'|'bar';
type User={id:number;name:string;username:string;roles:Role[]};
type StaffUser=User&{active:number};
type StaffEdit={id:number;name:string;username:string;roles:Role[]};
type MenuEdit={id:number;name:string;category:string;price:string};
type SizeEdit={id?:number;volume:string;price:string;active:boolean};
type DrinkEdit={key:string;name:string;category:string;straw:boolean;sizes:SizeEdit[]};
type Dish={id:number;name:string;category:string;station:string;price:number;active:number;straw:number};
type DiningTable={id:number;name:string;active:number};
type TableStatus={visit_id:number;table_id:number;table_name:string;opened_at:string;pending_count:number;ready_count:number;food_count:number;food_pending:number;food_waiting_since:string|null;waiting_since:string|null;unpaid_since:string|null;payment_due:boolean};
type ServiceMode='overview'|'order'|'payment';
type BillItem={id:number;menu_id:number;name:string;quantity:number;price:number;note:string;station:string;status:string;cancelled_at:string|null;cancellation_reason:string|null};
type BillChange={action:string;reason:string;actor:string;created_at:string;before_state:{name?:string;quantity?:number;note?:string}|null;after_state:{name?:string;quantity?:number;note?:string}|null};
type BillOrder={id:number;created_at:string;server:string;note:string;cancelled_at:string|null;paid_at:string|null;pending_count:number;can_pay:boolean;cancelled_by:string|null;cancellation_reason:string|null;items:BillItem[];total:number;changes:BillChange[]};
type Bill={table:DiningTable;visit_id:number|null;orders:BillOrder[];total:number;pending_count:number;can_pay:boolean};
type Line={menu_id:number;name:string;quantity:number;note:string};
type Ticket={id:number;order_id:number;table_id:number;station:Role;origin:string;status:string;created_at:string;started_at:string|null;collected_at:string|null;table_name:string;server:string;note:string;cancellation_reason:string|null;items:{id:number;name:string;quantity:number;note:string;cancelled_at:string|null;cancellation_reason:string|null}[];events?:{action:string;name:string;created_at:string}[]};
type StationAlert={id:number;ticket_id:number;kind:string;description:string;reason:string;created_at:string;order_id:number;station:Role;table_name:string;requested_by:string};
type PaidVisit={visit_id:number;table_id:number;table_name:string;paid_at:string;paid_by:string;amount:number};
type PaymentEvent={id:number;visit_id:number;order_id:number|null;action:'confirmed'|'reversed'|'order_paid';amount:number;reason:string;created_at:string;table_name:string;actor:string};
type Payments={paid:PaidVisit[];events:PaymentEvent[]};
type OrderEdit={orderId:number;mode:'add'|'replace'|'remove'|'note';itemId?:number;menuId:number;quantity:number;note:string;reason:string;requestKey:string};
const labels:Record<string,string>={service:'Service',kitchen:'Küche',bar:'Tresen',admin:'Admin',new:'Neu',working:'In Arbeit',ready:'Abholbereit',collected:'Abgeholt',cancelled:'Storniert',item_removed:'Position entfernt',note_changed:'Bestellnotiz geändert'};
// crypto.randomUUID() exists only on localhost/HTTPS; over plain HTTP in the WLAN fall back to getRandomValues.
const newKey=():string=>typeof crypto.randomUUID==='function'?crypto.randomUUID():Array.from(crypto.getRandomValues(new Uint8Array(16)),(b,i)=>(i===6?(b&15)|64:i===8?(b&63)|128:b).toString(16).padStart(2,'0')).join('').replace(/^(.{8})(.{4})(.{4})(.{4})/,'$1-$2-$3-$4-');
let csrf='';
let onSessionLost:(message:string)=>void=()=>{};
async function api(action:string,body?:unknown){const r=await fetch('/api/index.php?action='+action,{credentials:'same-origin',headers:body?{'Content-Type':'application/json','X-CSRF-Token':csrf}:{},method:body?'POST':'GET',body:body?JSON.stringify(body):undefined});const data=await r.json();if(r.status===401&&action!=='login'){const message='Sitzung beendet. '+(data.error||'Bitte anmelden.');onSessionLost(message);throw new Error(message);}if(!r.ok)throw new Error(data.error||'Verbindungsfehler');return data;}
const money=(n:number)=>(n/100).toLocaleString('de-DE',{style:'currency',currency:'EUR'});
const orderNumber=(id:number)=>'#'+String(id).padStart(6,'0');
// Sort by product name, then by the trailing "… 300 ml" size, so all sizes of a drink stay together.
const sizeKey=(name:string):[string,number]=>{const m=/^(.*?)\s+(\d+)\s*ml$/.exec(name);return m?[m[1],Number(m[2])]:[name,0];};
const byNameAndSize=(a:Dish,b:Dish)=>{const [an,av]=sizeKey(a.name),[bn,bv]=sizeKey(b.name);return an.localeCompare(bn,'de')||av-bv;};
// One menu card per product; its sizes are chosen after tapping the card.
const groupBySize=(list:Dish[])=>{const groups=new Map<string,Dish[]>();for(const d of [...list].sort(byNameAndSize)){const base=sizeKey(d.name)[0];groups.set(base,[...(groups.get(base)||[]),d]);}return [...groups].map(([name,items])=>({name,items}));};

function App(){
 const [user,setUser]=useState<User|null>(null),[loading,setLoading]=useState(true),[view,setView]=useState<Role>('service'),[error,setError]=useState(''),[message,setMessage]=useState('');
 const [menu,setMenu]=useState<Dish[]>([]),[tables,setTables]=useState<DiningTable[]>([]),[tickets,setTickets]=useState<Ticket[]>([]),[stationAlerts,setStationAlerts]=useState<StationAlert[]>([]),[tableStatuses,setTableStatuses]=useState<TableStatus[]>([]),[payments,setPayments]=useState<Payments>({paid:[],events:[]}),[reverseVisit,setReverseVisit]=useState<number|null>(null),[reverseReason,setReverseReason]=useState(''),[archive,setArchive]=useState(false),[online,setOnline]=useState(true),[now,setNow]=useState(Date.now()),[offset,setOffset]=useState(0);
 const [table,setTable]=useState<number|null>(null),[tableDrawer,setTableDrawer]=useState(false),[cart,setCart]=useState<Line[]>([]),[editingDraftIndex,setEditingDraftIndex]=useState<number|null>(null),[note,setNote]=useState(''),[search,setSearch]=useState(''),[menuGroup,setMenuGroup]=useState<'bar'|'kitchen'>('bar'),[sizePick,setSizePick]=useState<string|null>(null),[adminMenuGroup,setAdminMenuGroup]=useState<'bar'|'kitchen'>('bar'),[menuEdit,setMenuEdit]=useState<MenuEdit|null>(null),[barCover,setBarCover]=useState(false),[drinkEdit,setDrinkEdit]=useState<DrinkEdit|null>(null),[busy,setBusy]=useState(false),[key,setKey]=useState(newKey()),[users,setUsers]=useState<StaffUser[]>([]),[staffEdit,setStaffEdit]=useState<StaffEdit|null>(null);
 const [serviceMode,setServiceMode]=useState<ServiceMode>('overview'),[bill,setBill]=useState<Bill|null>(null),[cancelTarget,setCancelTarget]=useState<number|null>(null),[cancelReason,setCancelReason]=useState(''),[orderEdit,setOrderEdit]=useState<OrderEdit|null>(null);
 const can=(role:Role)=>!!user&&(user.roles.includes('admin')||user.roles.includes(role));
 const currentTable=tables.find(t=>Number(t.id)===table);
 const selectedTable=currentTable&&Number(currentTable.active)===1?currentTable:undefined;
 const readyTickets=tickets.filter(t=>t.status==='ready');
 const statusByTable=new Map(tableStatuses.map(s=>[s.table_id,s]));
 const unavailableLines=cart.filter(l=>!menu.some(m=>Number(m.id)===l.menu_id&&Number(m.active)===1));
 useEffect(()=>{api('session').then(d=>{csrf=d.csrf;setUser(d.user);if(d.user)setView(d.user.roles.includes('service')?'service':d.user.roles[0]);}).catch(e=>setError(e.message)).finally(()=>setLoading(false));const timer=setInterval(()=>setNow(Date.now()),1000);return()=>clearInterval(timer)},[]);
 function resetSession(){setUser(null);setTickets([]);setStationAlerts([]);setTableStatuses([]);setPayments({paid:[],events:[]});setCart([]);setEditingDraftIndex(null);setTable(null);setBill(null);setServiceMode('overview');}
 // Expired or revoked sessions return to the login; the saved draft stays in local storage for the same user.
 onSessionLost=message=>{resetSession();setError(message);api('session').then(d=>{csrf=d.csrf}).catch(()=>{});};
 async function refresh(){const [d,statuses]=await Promise.all([api('tickets&archive='+(archive?'1':'0')+'&view='+view),can('service')?api('table_status'):Promise.resolve(null)]);setTickets(d.tickets);setStationAlerts(d.alerts||[]);setBarCover(Boolean(d.bar_cover));if(statuses)setTableStatuses(statuses);setOffset(Date.parse(d.server_time.replace(' ','T')+'Z')-Date.now());setOnline(true);}
 async function refreshPayments(){if(can('service'))setPayments(await api('payments'));}
 async function catalog(){const [m,t]=await Promise.all([api('menu'),api('tables')]);setMenu(m);setTables(t);}
 useEffect(()=>{if(!user)return;catalog().catch(e=>setError(e.message));const timer=setInterval(()=>catalog().catch(()=>{}),10000);return()=>clearInterval(timer)},[user]);
 useEffect(()=>{if(!user)return;let active=true;const poll=async()=>{try{const [d,statuses]=await Promise.all([api('tickets&archive='+(archive?'1':'0')+'&view='+view),can('service')?api('table_status'):Promise.resolve(null)]);if(active){setTickets(d.tickets);setStationAlerts(d.alerts||[]);setBarCover(Boolean(d.bar_cover));if(statuses)setTableStatuses(statuses);setOffset(Date.parse(d.server_time.replace(' ','T')+'Z')-Date.now());setOnline(true);}}catch{if(active)setOnline(false)}};poll();const timer=setInterval(poll,2000);return()=>{active=false;clearInterval(timer)}},[user,archive,view]);
 useEffect(()=>{if(!user||!can('service'))return;let active=true;const poll=async()=>{try{const data=await api('payments');if(active)setPayments(data)}catch{}};poll();const timer=setInterval(poll,10000);return()=>{active=false;clearInterval(timer)}},[user]);
 useEffect(()=>{if(!user||serviceMode!=='payment'||table===null)return;let active=true;setBill(null);const load=async()=>{try{const data=await api('table_bill&table_id='+table);if(active)setBill(data)}catch(e){if(active)setError((e as Error).message)}};load();const timer=setInterval(load,3000);return()=>{active=false;clearInterval(timer)}},[user,serviceMode,table]);
 useEffect(()=>{if(!user)return;const saved=localStorage.getItem('draft-'+user.id);if(saved)try{const d=JSON.parse(saved);setCart(Array.isArray(d.cart)?d.cart:[]);setTable(typeof d.table==='number'?d.table:null);setNote(typeof d.note==='string'?d.note:'');setKey(typeof d.key==='string'?d.key:newKey());}catch{}},[user?.id]);
 useEffect(()=>{if(!tableDrawer)return;const close=(event:KeyboardEvent)=>{if(event.key==='Escape')setTableDrawer(false)};document.addEventListener('keydown',close);return()=>document.removeEventListener('keydown',close)},[tableDrawer]);
 function draft(lines:Line[],t:number|null=table,n=note,k=newKey()){setCart(lines);setTable(t);setNote(n);setKey(k);if(user)localStorage.setItem('draft-'+user.id,JSON.stringify({cart:lines,table:t,note:n,key:k}));}
 function updateDraftLine(index:number,change:Partial<Line>){draft(cart.map((line,i)=>i===index?{...line,...change}:line));}
 function removeDraftLine(index:number){draft(cart.filter((_,i)=>i!==index));setEditingDraftIndex(null);}
 function chooseTable(id:number,mode:ServiceMode='overview'){if(id!==table&&cart.length&&!window.confirm('Ungesendeten Entwurf für '+(selectedTable?.name||'den bisherigen Tisch')+' verwerfen und Tisch wechseln?'))return;draft(id===table?cart:[],id,id===table?note:'');setEditingDraftIndex(null);setServiceMode(mode);setBill(null);setCancelTarget(null);setOrderEdit(null);setReverseVisit(null);setReverseReason('');setTableDrawer(false);}
 async function run(fn:()=>Promise<void>){setError('');setMessage('');setBusy(true);try{await fn()}catch(e){setError((e as Error).message)}finally{setBusy(false)}}
 async function status(t:Ticket,target:string){await run(async()=>{await api('status',{id:Number(t.id),status:target});await refresh();setMessage(target==='collected'?'Abholung bestätigt.':'Bon aktualisiert.');});}
 async function acknowledgeAlert(alert:StationAlert){await run(async()=>{await api('station_alert_ack',{id:Number(alert.id)});await refresh();setMessage('Stornohinweis für '+alert.table_name+' bestätigt.');});}
 async function markPaid(receipt:Bill){if(receipt.visit_id===null||!window.confirm(`${receipt.table.name}: ${money(receipt.total)} als erhalten markieren?`))return;await run(async()=>{await api('table_paid',{visit_id:receipt.visit_id,expected_total:receipt.total});setServiceMode('overview');setBill(null);await Promise.all([refresh(),refreshPayments()]);setMessage(`${receipt.table.name}: Zahlung über ${money(receipt.total)} bestätigt.`);});}
 async function markOrderPaid(order:BillOrder){if(table===null||!window.confirm(`Bestellung ${orderNumber(order.id)}: ${money(order.total)} als erhalten markieren?`))return;const tableId=table;await run(async()=>{const result=await api('order_paid',{order_id:order.id,expected_total:order.total});if(result.visit_closed){setServiceMode('overview');setBill(null);}else setBill(await api('table_bill&table_id='+tableId));await Promise.all([refresh(),refreshPayments()]);setMessage(`Bestellung ${orderNumber(order.id)}: Zahlung über ${money(order.total)} bestätigt.`+(result.visit_closed?' Tisch ist vollständig bezahlt.':''));});}
 async function reversePayment(){if(reverseVisit===null||!reverseReason.trim())return;const visitId=reverseVisit;await run(async()=>{await api('payment_reverse',{visit_id:visitId,reason:reverseReason.trim()});setReverseVisit(null);setReverseReason('');await Promise.all([refresh(),refreshPayments()]);setMessage('Zahlungsbestätigung zurückgenommen. Der Tisch ist wieder als offen markiert.');});}
 async function cancelOrder(order:BillOrder){if(!cancelReason.trim())return;await run(async()=>{await api('order_cancel',{order_id:order.id,reason:cancelReason.trim()});setBill(await api('table_bill&table_id='+table));await refresh();setCancelTarget(null);setCancelReason('');setMessage(`Bestellung ${orderNumber(order.id)} storniert.`);});}
 function beginOrderEdit(order:BillOrder,mode:OrderEdit['mode'],item?:BillItem){const first=menu.find(m=>Number(m.active)===1);setCancelTarget(null);setOrderEdit({orderId:order.id,mode,itemId:item?.id,menuId:item&&menu.some(m=>Number(m.id)===item.menu_id&&Number(m.active)===1)?item.menu_id:first?.id||0,quantity:item?.quantity||1,note:mode==='note'?order.note:item?.note||'',reason:'',requestKey:newKey()});}
 async function saveOrderEdit(){if(!orderEdit||!orderEdit.reason.trim())return;const edit=orderEdit;await run(async()=>{await api('order_change',{order_id:edit.orderId,mode:edit.mode,request_key:edit.requestKey,reason:edit.reason.trim(),item_id:edit.itemId,menu_id:edit.mode==='add'||edit.mode==='replace'?edit.menuId:undefined,quantity:edit.mode==='add'||edit.mode==='replace'?edit.quantity:undefined,note:edit.note});setBill(await api('table_bill&table_id='+table));await refresh();setOrderEdit(null);setMessage(`Bestellung ${orderNumber(edit.orderId)} aktualisiert.`);});}
 async function saveStaff(e:React.FormEvent<HTMLFormElement>){e.preventDefault();if(!staffEdit||staffEdit.roles.length===0)return;const edited=staffEdit;await run(async()=>{await api('admin_user_update',edited);setUsers(await api('admin_users'));if(edited.id===user?.id){const session=await api('session');setUser(session.user);}setStaffEdit(null);setMessage('Mitarbeiter aktualisiert.');});}
 async function changeStaffStatus(person:StaffUser,active:boolean){if(!active&&!window.confirm(person.name+' entfernen? Der Zugang wird gesperrt; frühere Bestellungen bleiben erhalten.'))return;await run(async()=>{await api('admin_user_status',{id:Number(person.id),active});setUsers(await api('admin_users'));setStaffEdit(null);setMessage(active?'Mitarbeiter wieder aktiviert.':'Mitarbeiter entfernt.');});}
 async function login(e:React.FormEvent<HTMLFormElement>){e.preventDefault();const f=new FormData(e.currentTarget);await run(async()=>{const d=await api('login',Object.fromEntries(f));csrf=d.csrf;setUser(d.user);setView(d.user.roles.includes('service')?'service':d.user.roles[0]);});}
 // Runs only while a bon is new; afterwards it stays at the wait until start (archive: until pickup).
 const elapsed=(t:Ticket)=>{const at=(d:string)=>Date.parse(d.replace(' ','T')+'Z');const stop=t.status==='new'?now+offset:t.status==='collected'&&t.collected_at?at(t.collected_at):t.started_at?at(t.started_at):null;if(stop===null)return null;const sec=Math.max(0,Math.floor((stop-at(t.created_at))/1000));return `${Math.floor(sec/60).toString().padStart(2,'0')}:${(sec%60).toString().padStart(2,'0')}`+(t.status==='new'?'':t.status==='collected'?' bis Abholung':' bis Start');};
 const minutesSince=(date:string|null)=>date?Math.max(0,Math.floor((now+offset-Date.parse(date.replace(' ','T')+'Z'))/60000)):0;
 function tablePhase(s:TableStatus){if(s.food_pending>0){const mins=minutesSince(s.food_waiting_since);return {kind:mins>=30?'critical':mins>=15?'late':'waiting',label:mins>=30?'Sehr lange Wartezeit':mins>=15?'Lange Wartezeit':'Wartet auf Essen',detail:`${mins} Min. auf Essen`};}if(s.ready_count>0)return {kind:'ready',label:'Abholbereit',detail:`${s.ready_count} ${s.ready_count===1?'Bon':'Bons'} abholbereit`};if(s.payment_due)return {kind:'unpaid',label:'Zahlung offen',detail:s.pending_count>0?'Getränke noch offen':`Seit ${minutesSince(s.unpaid_since)} Min. offen`};return {kind:'waiting',label:'Wartet auf Getränke',detail:`${minutesSince(s.waiting_since)} Min. Wartezeit`};}
 const orderedStatuses=[...tableStatuses].sort((a,b)=>{const priority:Record<string,number>={critical:0,late:1,ready:2,unpaid:3,waiting:4};return priority[tablePhase(a).kind]-priority[tablePhase(b).kind]||a.table_id-b.table_id;});
 const statusOrder=new Map(orderedStatuses.map((s,i)=>[s.table_id,i]));
 const orderedTables=[...tables].filter(t=>Number(t.active)===1||statusByTable.has(Number(t.id))||payments.paid.some(p=>p.table_id===Number(t.id))).sort((a,b)=>(statusOrder.get(Number(a.id))??999)-(statusOrder.get(Number(b.id))??999)||Number(a.id)-Number(b.id));
 // Service may work drink tickets while nobody staffs the bar (server decides via bar_cover).
 const canWork=(station:string)=>can(station as Role)||(station==='bar'&&barCover);
 function ticket(t:Ticket){
  const wait=t.station==='kitchen'&&['new','working'].includes(t.status)?minutesSince(t.created_at):0;
  return <article className={'ticket '+t.status+(wait>=30?' wait-critical':wait>=15?' wait-late':'')} key={t.id}>
   <div className="row"><h2>{t.table_name}</h2>{elapsed(t)&&<strong className={'timer'+(t.status==='new'?'':' stopped')}>◷ {elapsed(t)}</strong>}</div>
   {wait>=15&&<strong className="wait-note">{wait>=30?'Sehr lange Wartezeit':'Lange Wartezeit'} · {wait} Min. auf Essen</strong>}
   <small>Bestellung {orderNumber(Number(t.order_id))} · Bon #{t.id} · {labels[t.station]} · Eingang {new Date(t.created_at.replace(' ','T')+'Z').toLocaleTimeString('de-DE',{hour:'2-digit',minute:'2-digit'})}</small>
   {t.origin!=='initial'&&<strong className="ticket-origin">{t.origin==='addition'?'Nachtrag':'Korrektur'} zu Bestellung {orderNumber(Number(t.order_id))}</strong>}
   {t.items.map(i=><div className={'item '+(i.cancelled_at?'ticket-item-cancelled':'')} key={i.id}><b>{i.quantity}× {i.name}</b>{i.note&&<mark>{i.note}</mark>}{i.cancelled_at&&<small>Position entfernt · {i.cancellation_reason}</small>}</div>)}
   {t.note&&<mark>Bestellnotiz: {t.note}</mark>}
   {t.status==='cancelled'&&<p className="cancel-note">Storniert · {t.cancellation_reason||t.items.find(i=>i.cancelled_at)?.cancellation_reason}</p>}
   <p className="muted">Service: {t.server}</p>
   {t.status==='new'&&canWork(t.station)&&<button disabled={busy||!online} onClick={()=>status(t,'working')}>Zubereitung starten →</button>}
   {t.status==='working'&&canWork(t.station)&&<button disabled={busy||!online} onClick={()=>status(t,'ready')}>✓ Abholbereit</button>}
   {t.status==='ready'&&(can('service')?<button disabled={busy||!online} onClick={()=>status(t,'collected')}>Abholung bestätigen</button>:<div className="notice">Service benachrichtigt · wartet auf Abholung</div>)}
   {t.events&&<details><summary>Verlauf ansehen</summary>{t.events.map((e,i)=><p key={i}>{labels[e.action]||e.action} · {e.name} · {new Date(e.created_at.replace(' ','T')+'Z').toLocaleTimeString('de-DE')}</p>)}</details>}
  </article>;
 }
 function cashier(){
  if(!currentTable)return null;
  const activeOrders=bill?.orders.filter(o=>!o.cancelled_at)||[];
  const unpaidOrders=activeOrders.filter(o=>!o.paid_at);
  const cancelledOrders=bill?.orders.filter(o=>o.cancelled_at)||[];
  const editTitle:Record<OrderEdit['mode'],string>={add:'Position ergänzen',replace:'Position korrigieren',remove:'Position entfernen',note:'Bestellnotiz ändern'};
  const changeText=(c:BillChange)=>c.action==='note'?'Bestellnotiz geändert: '+(c.before_state?.note||'ohne Notiz')+' → '+(c.after_state?.note||'ohne Notiz'):c.action==='order_cancel'?'Bestellung storniert':c.action==='add'?'Ergänzt: '+c.after_state?.quantity+'× '+c.after_state?.name:c.action==='remove'?'Entfernt: '+c.before_state?.quantity+'× '+c.before_state?.name:'Korrigiert: '+c.before_state?.quantity+'× '+c.before_state?.name+' → '+c.after_state?.quantity+'× '+c.after_state?.name;
  return <section className="cashier" aria-label="Kassieren">
   <div className="cashier-heading"><div><small>KASSIEREN · {currentTable.name.toUpperCase()}</small><h2>Offene Rechnung</h2><p>Alle Speisen und Getränke des aktuellen Tischbesuchs mit ihrer Bestellnummer.</p></div><span className="cashier-total">{bill?money(bill.total):'…'}</span></div>
   {!bill?<p className="empty">Rechnung wird geladen …</p>:<>
    {activeOrders.length===0?<div className="empty">Für diesen Tisch gibt es derzeit keine abzurechnenden Bestellungen.</div>:<div className="bill-orders">{activeOrders.map(o=><article className={'bill-order'+(o.paid_at?' paid':'')} key={o.id}>
     <div className="bill-order-heading"><div><strong>Bestellung {orderNumber(o.id)}{o.paid_at&&<span className="paid-badge">Bezahlt</span>}</strong><small>{new Date(o.created_at.replace(' ','T')+'Z').toLocaleString('de-DE',{dateStyle:'short',timeStyle:'short'})} · {o.server}</small></div><b>{money(o.total)}</b></div>
     {o.items.map(item=><div className={'bill-item '+(item.cancelled_at?'cancelled':'')} key={item.id}><span><b>{item.quantity}× {item.name}</b><small>{item.cancelled_at?'Entfernt · '+item.cancellation_reason:labels[item.station]+' · '+labels[item.status]+(item.note?' · '+item.note:'')}</small>{!item.cancelled_at&&!o.paid_at&&<span className="item-actions"><button type="button" className="ghost" disabled={busy||!online} onClick={()=>beginOrderEdit(o,'replace',item)}>Korrigieren</button><button type="button" className="ghost" disabled={busy||!online} onClick={()=>beginOrderEdit(o,'remove',item)}>Entfernen</button></span>}</span><strong>{item.cancelled_at?'–':money(item.quantity*item.price)}</strong></div>)}
     {o.note&&<p className="bill-note">Bestellnotiz: {o.note}</p>}
     {!o.paid_at&&unpaidOrders.length>1&&<div className="order-pay"><button type="button" disabled={busy||!online||!o.can_pay||!!orderEdit} onClick={()=>markOrderPaid(o)}>Nur {orderNumber(o.id)} bezahlt · {money(o.total)}</button>{o.pending_count>0&&<small>{o.pending_count} {o.pending_count===1?'Position ist':'Positionen sind'} noch nicht abgeholt.</small>}</div>}
     {!o.paid_at&&<div className="order-actions"><button type="button" className="ghost" disabled={busy||!online||!selectedTable} onClick={()=>beginOrderEdit(o,'add')}>+ Position ergänzen</button><button type="button" className="ghost" disabled={busy||!online} onClick={()=>beginOrderEdit(o,'note')}>Bestellnotiz ändern</button></div>}
     {orderEdit?.orderId===o.id&&<form className="order-edit" onSubmit={e=>{e.preventDefault();saveOrderEdit()}}>
      <strong>{editTitle[orderEdit.mode]} · {orderNumber(o.id)}</strong>
      {orderEdit.itemId&&<p>{o.items.find(i=>i.id===orderEdit.itemId)?.quantity}× {o.items.find(i=>i.id===orderEdit.itemId)?.name}</p>}
      {(orderEdit.mode==='add'||orderEdit.mode==='replace')&&<><label>Produkt<select required value={orderEdit.menuId||''} onChange={e=>setOrderEdit({...orderEdit,menuId:Number(e.target.value)})}>{menu.filter(m=>Number(m.active)===1).map(m=><option key={m.id} value={m.id}>{m.name} · {money(m.price)}</option>)}</select></label><label>Anzahl<input type="number" min="1" max="50" required value={orderEdit.quantity} onChange={e=>setOrderEdit({...orderEdit,quantity:Number(e.target.value)})}/></label><label>Hinweis zur Position<input maxLength={500} value={orderEdit.note} onChange={e=>setOrderEdit({...orderEdit,note:e.target.value})}/></label></>}
      {orderEdit.mode==='note'&&<label>Bestellnotiz<textarea maxLength={500} value={orderEdit.note} onChange={e=>setOrderEdit({...orderEdit,note:e.target.value})}/></label>}
      <label>Grund der Änderung<input required maxLength={300} value={orderEdit.reason} onChange={e=>setOrderEdit({...orderEdit,reason:e.target.value})} placeholder="z. B. Gastwunsch oder falsch erfasst"/></label>
      <div className="row"><button type="button" className="ghost" disabled={busy} onClick={()=>setOrderEdit(null)}>Abbrechen</button><button type="submit" disabled={busy||!online||!orderEdit.reason.trim()||((orderEdit.mode==='add'||orderEdit.mode==='replace')&&!menu.some(m=>Number(m.id)===orderEdit.menuId&&Number(m.active)===1))}>{busy?'Wird gespeichert …':'Änderung speichern'}</button></div>
     </form>}
     {o.changes.length>0&&<details className="change-history"><summary>Änderungsverlauf ({o.changes.length})</summary>{o.changes.map((c,i)=><p key={i}><b>{changeText(c)}</b><small>{c.actor} · {new Date(c.created_at.replace(' ','T')+'Z').toLocaleString('de-DE',{dateStyle:'short',timeStyle:'short'})} · Grund: {c.reason}</small></p>)}</details>}
     {o.paid_at?null:cancelTarget===o.id?<div className="cancel-form"><label>Stornogrund<input maxLength={300} value={cancelReason} onChange={e=>setCancelReason(e.target.value)} placeholder="Warum wird die Bestellung storniert?"/></label><div className="row"><button className="ghost" disabled={busy} onClick={()=>{setCancelTarget(null);setCancelReason('')}}>Abbrechen</button><button className="danger" disabled={busy||!online||!cancelReason.trim()} onClick={()=>cancelOrder(o)}>Stornierung bestätigen</button></div></div>:<button className="cancel-trigger" disabled={busy||!online} onClick={()=>{setOrderEdit(null);setCancelTarget(o.id);setCancelReason('')}}>Bestellung {orderNumber(o.id)} stornieren</button>}
    </article>)}</div>}
    {cancelledOrders.length>0&&<details className="cancelled-orders"><summary>{cancelledOrders.length} stornierte {cancelledOrders.length===1?'Bestellung':'Bestellungen'} ansehen</summary>{cancelledOrders.map(o=><div className="cancelled-order" key={o.id}><b>Bestellung {orderNumber(o.id)}</b><span>{o.cancellation_reason} · {o.cancelled_by}</span><small>{o.items.map(i=>String(i.quantity)+'× '+i.name).join(', ')}</small></div>)}</details>}
    <div className="cashier-footer"><div><span>Zu kassieren</span><strong>{money(bill.total)}</strong></div>{bill.pending_count>0&&<p className="payment-wait">{bill.pending_count} {bill.pending_count===1?'Bon ist':'Bons sind'} noch nicht abgeholt. Zahlung kann danach bestätigt werden.</p>}<button disabled={busy||!online||!bill.can_pay||!!orderEdit} onClick={()=>markPaid(bill)}>{busy?'Wird verarbeitet …':(unpaidOrders.length<activeOrders.length?'Restbetrag ':'Alles · ')+money(bill.total)+' als bezahlt markieren'}</button><small>{unpaidOrders.length>1?'Bei getrennter Zahlung einzelne Bestellungen oben als bezahlt markieren. ':''}Diese Bestätigung erfasst alle noch offenen Bestellungen des Tischbesuchs.</small></div>
   </>}
  </section>;
 }
 if(loading)return <div className="login">Wird geladen …</div>;
 if(!user)return <main className="login"><div className="brand">Zum Stimbeck ♧</div><h1>Willkommen im Team.</h1><p className="muted">Küche, Tresen und Service. Gemeinsam im Takt.</p><form onSubmit={login}><label>Benutzername<input name="username" autoComplete="username" required/></label><label>Passwort<input name="password" type="password" autoComplete="current-password" required/></label>{error&&<p role="alert" className="error">{error}</p>}<button disabled={busy}>Anmelden →</button></form><small>Lokale Demo · Zugangsdaten in der README</small></main>;
 const shown=tickets.filter(t=>view==='service'||view==='admin'||t.station===view);
 const visibleAlerts=stationAlerts.filter(a=>a.station===view||(view==='service'&&barCover&&a.station==='bar'));
 const reversiblePayments=currentTable?payments.paid.filter(p=>p.table_id===Number(currentTable.id)):payments.paid.slice(0,5);
 // Drink editor: one drink, one row per portion size with its own price. Existing sizes are deactivated, never deleted, because orders reference them.
 const drinkForm=(edit:DrinkEdit)=>{const setSize=(i:number,change:Partial<SizeEdit>)=>setDrinkEdit({...edit,sizes:edit.sizes.map((size,j)=>j===i?{...size,...change}:size)});return <form className="staff-edit" onSubmit={e=>{e.preventDefault();run(async()=>{await api('admin_drink',{name:edit.name,category:edit.category,straw:edit.straw,sizes:edit.sizes.map(size=>({...(size.id?{id:size.id}:{}),volume_ml:Number(size.volume),price:Math.round(Number(size.price)*100),active:size.active}))});await catalog();setDrinkEdit(null);setMessage(edit.key==='new'?'Getränk angelegt.':'Getränk gespeichert. Bereits gesendete Bestellungen behalten Name und Preis.');});}}>
  <strong>{edit.key==='new'?'Neues Getränk':edit.key+' bearbeiten'}</strong>
  <label>Getränkename ohne Menge<input required maxLength={100} value={edit.name} onChange={e=>setDrinkEdit({...edit,name:e.target.value})}/></label>
  <label>Kategorie<input required maxLength={40} list="categories-bar" value={edit.category} onChange={e=>setDrinkEdit({...edit,category:e.target.value})}/></label>
  <fieldset><legend>Portionsgrößen · je Größe ein Preis</legend>{edit.sizes.map((size,i)=><div className="size-row" key={size.id??'neu-'+i}>
   <label>Menge (ml)<input required type="number" min="1" max="5000" step="1" value={size.volume} onChange={e=>setSize(i,{volume:e.target.value})}/></label>
   <label>Preis (€)<input required type="number" min="0" step="0.01" value={size.price} onChange={e=>setSize(i,{price:e.target.value})}/></label>
   {size.id?<label className="check"><input type="checkbox" checked={size.active} onChange={e=>setSize(i,{active:e.target.checked})}/>Verfügbar</label>:<button type="button" className="ghost" disabled={edit.sizes.length===1} onClick={()=>setDrinkEdit({...edit,sizes:edit.sizes.filter((_,j)=>j!==i)})}>Entfernen</button>}
  </div>)}<button type="button" className="ghost" disabled={edit.sizes.length>=6} onClick={()=>setDrinkEdit({...edit,sizes:[...edit.sizes,{volume:'',price:'',active:true}]})}>+ Weitere Größe</button></fieldset>
  <label className="check"><input type="checkbox" checked={edit.straw} onChange={e=>setDrinkEdit({...edit,straw:e.target.checked})}/>Strohhalm-Option (Kindergetränk)</label>
  <div className="row"><button type="button" className="ghost" disabled={busy} onClick={()=>setDrinkEdit(null)}>Abbrechen</button><button type="submit" disabled={busy}>{edit.key==='new'?'Getränk anlegen':'Änderungen speichern'}</button></div>
 </form>;};
 return <><header><div className="brand">Zum Stimbeck ♧</div><nav>{(['service','kitchen','bar','admin'] as Role[]).filter(can).map(r=><button className={view===r?'':'ghost'} key={r} onClick={()=>{setView(r);setArchive(false);if(r==='admin')api('admin_users').then(setUsers).catch(e=>setError(e.message));}}>{labels[r]}</button>)}</nav><span className={online?'live':'error'}>{online?'● Live':'● Verbindung unterbrochen'}</span><span>{user.name}</span><button className="ghost" onClick={()=>run(async()=>{await api('logout',{});resetSession();const d=await api('session');csrf=d.csrf;})}>Abmelden</button></header>
 <main>{error&&<div role="alert" className="error banner">{error}</div>}{message&&<div role="status" className="notice banner">{message}</div>}{!online&&<div className="error banner">Offline – Daten möglicherweise veraltet. Bestellungen werden erst nach Serverbestätigung als gesendet angezeigt.</div>}
 <div className="row page-title"><div><h1>{view==='service'?'Guter Service beginnt hier.':view==='admin'?'Alles gut organisiert.':`Alles im Blick, ${user.name}.`}</h1><p className="muted">{new Date().toLocaleDateString('de-DE',{weekday:'long',day:'numeric',month:'long'})} · {labels[view]}</p></div>{view!=='admin'&&<button className="ghost" onClick={()=>setArchive(!archive)}>{archive?'← Aktuelle Bons':'▣ Archiv'}</button>}</div>
 {!archive&&visibleAlerts.length>0&&<section className="station-alerts" aria-label="Stornos zur Bestätigung"><h2>{visibleAlerts.length} {visibleAlerts.length===1?'Storno benötigt':'Stornos benötigen'} deine Bestätigung</h2>{visibleAlerts.map(alert=><article key={alert.id} className="station-alert"><div><strong>{alert.table_name} · Bestellung {orderNumber(Number(alert.order_id))}</strong><p>{alert.description}</p><small>Grund: {alert.reason} · {alert.requested_by}</small></div><button disabled={busy||!online} onClick={()=>acknowledgeAlert(alert)}>Storno gesehen ✓</button></article>)}</section>}
 {view==='service'&&barCover&&!archive&&<div role="status" className="notice banner">Tresen ist gerade nicht besetzt. Du übernimmst die Getränkebons bis „Abholbereit“.</div>}
 {view==='service'&&!archive&&<>
  {readyTickets.length>0&&<section className="ready-strip" aria-label="Abholbereite Bestellungen"><div className="ready-heading"><span className="ready-pulse" aria-hidden="true"/><strong>{readyTickets.length} {readyTickets.length===1?'Bestellung wartet':'Bestellungen warten'} auf Abholung</strong></div>{readyTickets.map(t=><div className="ready-row" key={t.id}><span><b>{t.table_name}</b><small>Bestellung {orderNumber(Number(t.order_id))} · {labels[t.station]} · Bon #{t.id}</small></span><button disabled={busy||!online} onClick={()=>status(t,'collected')}>Abholung bestätigen</button></div>)}</section>}
  <div className="table-bar"><div><small>AKTUELLER TISCH</small><strong>{currentTable?.name||'Noch kein Tisch gewählt'}</strong>{currentTable&&<span>{statusByTable.get(Number(table))?tablePhase(statusByTable.get(Number(table))!).label:selectedTable?'Frei · keine offenen Besuche':'Deaktiviert · keine neuen Bestellungen'}</span>}</div><button type="button" onClick={()=>setTableDrawer(true)}>{currentTable?'Tisch wechseln':'Tisch wählen'} <span aria-hidden="true">☰</span></button></div>
  {currentTable&&<nav className="service-modes" aria-label="Servicebereich"><button className={serviceMode==='overview'?'active':''} aria-current={serviceMode==='overview'?'page':undefined} onClick={()=>setServiceMode('overview')}>Übersicht</button><button className={serviceMode==='order'?'active':''} aria-current={serviceMode==='order'?'page':undefined} disabled={!selectedTable} onClick={()=>setServiceMode('order')}>Bestellung aufnehmen{cart.length>0?` · ${cart.length}`:''}</button><button className={serviceMode==='payment'?'active':''} aria-current={serviceMode==='payment'?'page':undefined} onClick={()=>setServiceMode('payment')}>Kassieren</button></nav>}
  {serviceMode==='overview'&&<section className="table-status-overview" aria-label="Tischstatus"><div className="table-status-heading"><div><h2>Tischstatus</h2><p>{orderedStatuses.length?`${orderedStatuses.length} ${orderedStatuses.length===1?'Tisch hat':'Tische haben'} einen offenen Besuch`:'Alle Tische frei'}</p></div><small>Blau: Bestellung ausstehend · Rot: lange Wartezeit · Violett: Zahlung offen</small></div>{orderedStatuses.length>0&&<div className="table-status-list">{orderedStatuses.map(s=>{const phase=tablePhase(s);return <article className={'table-status-card '+phase.kind} key={s.visit_id}><button className="table-status-select" disabled={busy} onClick={()=>chooseTable(s.table_id)}><b>{s.table_name}</b><strong>{phase.label}</strong><span>{phase.detail}</span>{s.ready_count>0&&s.food_pending>0&&<span>{s.ready_count} Bon abholbereit</span>}</button>{s.payment_due&&s.pending_count===0&&<button className="payment-button" disabled={busy} onClick={()=>chooseTable(s.table_id,'payment')}>Rechnung ansehen →</button>}</article>})}</div>}</section>}
  {serviceMode==='overview'&&<section className="payment-history" aria-label="Letzte Zahlungsbestätigungen"><div className="row"><div><h2>Letzte Zahlungsbestätigungen</h2><small>Zum Korrigieren den betreffenden Tisch wählen. Die Rücknahme ändert nur den Status in dieser App; Geldbewegungen bitte separat in der Kasse berichtigen.</small></div></div>{reversiblePayments.length===0?<p className="muted">{currentTable?'Für diesen Tisch ist keine Zahlungsbestätigung rücknehmbar.':'Noch keine rücknehmbare Zahlungsbestätigung.'}</p>:<div className="payment-records">{reversiblePayments.map(p=><article key={p.visit_id} className="payment-record"><div><b>{p.table_name} · {money(p.amount)}</b><small>Bestätigt von {p.paid_by} · {new Date(p.paid_at.replace(' ','T')+'Z').toLocaleString('de-DE')}</small></div>{reverseVisit===p.visit_id?<form onSubmit={e=>{e.preventDefault();reversePayment()}}><label>Grund der Rücknahme<input required maxLength={300} value={reverseReason} onChange={e=>setReverseReason(e.target.value)} placeholder="z. B. Zahlung irrtümlich bestätigt"/></label><div className="row"><button type="button" className="ghost" onClick={()=>{setReverseVisit(null);setReverseReason('')}}>Abbrechen</button><button className="danger" disabled={busy||!online||!reverseReason.trim()}>Rücknahme bestätigen</button></div></form>:<button type="button" className="ghost" disabled={busy||!online} onClick={()=>{setReverseVisit(p.visit_id);setReverseReason('')}}>Bestätigung zurücknehmen</button>}</article>)}</div>}{payments.events.length>0&&<details><summary>Zahlungsverlauf ansehen</summary>{payments.events.map(e=><p key={e.id} className="payment-event"><b>{e.action==='confirmed'?'Bestätigt':e.action==='order_paid'?'Bestellung '+orderNumber(Number(e.order_id))+' bezahlt':'Zurückgenommen'} · {e.table_name} · {money(e.amount)}</b><small>{e.actor} · {new Date(e.created_at.replace(' ','T')+'Z').toLocaleString('de-DE')}{e.reason?' · Grund: '+e.reason:''}</small></p>)}</details>}</section>}
  {serviceMode==='order'&&selectedTable?<div className="service-layout"><section className="menu-section"><div className="row"><h2>Speisekarte</h2><input placeholder={menuGroup==='bar'?'Getränk suchen …':'Gericht suchen …'} aria-label="Produkt suchen" value={search} onChange={e=>setSearch(e.target.value)}/></div><div className="categories">{([['bar','Getränke'],['kitchen','Speisen']] as const).map(([group,label])=><button className={menuGroup===group?'':'ghost'} aria-pressed={menuGroup===group} onClick={()=>{setMenuGroup(group);setSizePick(null)}} key={group}>{label}</button>)}</div><div className="menu-grid">{groupBySize(menu.filter(m=>m.station===menuGroup&&m.name.toLowerCase().includes(search.toLowerCase()))).map(g=>{const available=g.items.filter(m=>Number(m.active)===1),sized=g.items.length>1,add=(m:Dish)=>{draft([...cart,{menu_id:Number(m.id),name:m.name,quantity:1,note:''}]);setSizePick(null);};
   if(sized&&sizePick===g.name)return <div className="dish size-pick" key={g.name}><b>{g.name}</b><span className="muted">Menge wählen</span><div className="sizes">{g.items.map(m=><button type="button" key={m.id} disabled={busy||Number(m.active)!==1} onClick={()=>add(m)}>{sizeKey(m.name)[1]} ml<small>{Number(m.active)===1?money(Number(m.price)):'Nicht verfügbar'}</small></button>)}</div><button type="button" className="ghost" onClick={()=>setSizePick(null)}>Abbrechen</button></div>;
   return <button disabled={busy||!available.length} className={'dish '+(available.length?'':'unavailable')} key={g.name} aria-expanded={sized?false:undefined} onClick={()=>sized?setSizePick(g.name):add(g.items[0])}><span className="dish-icon">{menuGroup==='bar'?'♧':'♨'}</span><b>{sized?g.name:g.items[0].name}</b>{sized&&<small className="muted">{g.items.map(m=>sizeKey(m.name)[1]).join(' · ')} ml</small>}<span className="row muted">{sized?'ab '+money(Math.min(...(available.length?available:g.items).map(m=>Number(m.price)))):money(Number(g.items[0].price))} {available.length?<strong>＋</strong>:<em>Nicht verfügbar</em>}</span></button>;})}</div></section>
  <section className="cart">
   <div className="cart-table-label">BESTELLUNG FÜR</div>
   <h2>{selectedTable.name}</h2>
   <p className="muted">Neue Bestellung · die Bestellnummer wird beim Senden vergeben</p>
   {cart.length===0&&<div className="empty">Wähle Speisen und Getränke aus.</div>}
   {cart.map((l,i)=>{
    const product=menu.find(m=>Number(m.id)===l.menu_id);
    const unavailable=!product||Number(product.active)!==1;
    return <div className="cart-line" key={i}>
     <div className="draft-line-heading"><b>{l.name}</b><button type="button" className="ghost" disabled={busy} onClick={()=>removeDraftLine(i)}>Entfernen</button></div>
     {product&&<small>{money(Number(product.price))} je Stück · {money(Number(product.price)*l.quantity)} gesamt</small>}
     {unavailable&&<small className="unavailable-note">Nicht mehr verfügbar · Produkt ändern oder entfernen</small>}
     <div className="draft-line-actions"><button type="button" className="ghost" disabled={busy} onClick={()=>setEditingDraftIndex(editingDraftIndex===i?null:i)}>{editingDraftIndex===i?'Bearbeitung schließen':'Produkt oder Menge ändern'}</button></div>
     {editingDraftIndex===i&&<div className="draft-line-edit">
      <label>Produkt<select aria-label={'Produkt für Position '+(i+1)} disabled={busy} value={l.menu_id} onChange={e=>{const next=menu.find(m=>Number(m.id)===Number(e.target.value));if(next)updateDraftLine(i,{menu_id:Number(next.id),name:next.name})}}>{menu.filter(m=>Number(m.active)===1||Number(m.id)===l.menu_id).sort(byNameAndSize).map(m=><option key={m.id} value={m.id} disabled={Number(m.active)!==1}>{m.name} · {Number(m.active)===1?money(Number(m.price)):'Nicht verfügbar'}</option>)}</select></label>
      <label>Menge<input aria-label={'Menge für Position '+(i+1)} type="number" min="1" max="50" disabled={busy} value={l.quantity} onChange={e=>{if(e.target.value!=='')updateDraftLine(i,{quantity:Math.max(1,Math.min(50,Number(e.target.value)||1))})}}/></label>
     </div>}
     <div className="row"><button type="button" disabled={busy} className="ghost" aria-label={'Weniger '+l.name} onClick={()=>l.quantity>1?updateDraftLine(i,{quantity:l.quantity-1}):removeDraftLine(i)}>−</button><span>{l.quantity}</span><button type="button" disabled={busy||l.quantity>=50||unavailable} className="ghost" aria-label={'Mehr '+l.name} onClick={()=>updateDraftLine(i,{quantity:l.quantity+1})}>＋</button></div>
     <input disabled={busy} aria-label={'Sonderwunsch '+l.name} maxLength={200} placeholder="Sonderwunsch …" value={l.note} onChange={e=>updateDraftLine(i,{note:e.target.value})}/>
     {(product?.station!=='bar'||Number(product.straw)===1)&&<div className="chips">{(product?.station==='bar'?['Mit Strohhalm']:['Ohne Tomate','Extra Gurke','Sauce separat']).map(s=><button type="button" disabled={busy} className={l.note.split(' · ').includes(s)?'':'ghost'} aria-pressed={l.note.split(' · ').includes(s)} key={s} onClick={()=>updateDraftLine(i,{note:l.note.includes(s)?l.note.split(' · ').filter(n=>n!==s).join(' · '):[l.note,s].filter(Boolean).join(' · ')})}>{s}</button>)}</div>}
    </div>;
   })}
   <textarea disabled={busy} placeholder="Notiz für Küche oder Tresen …" aria-label="Bestellnotiz" maxLength={300} value={note} onChange={e=>draft(cart,table,e.target.value)}/>
   {unavailableLines.length>0&&<p className="error">Nicht verfügbare Produkte im Entwurf ändern oder entfernen.</p>}
   <button disabled={busy||!online||!cart.length||unavailableLines.length>0||cart.some(l=>!Number.isInteger(l.quantity)||l.quantity<1||l.quantity>50)} onClick={()=>run(async()=>{const placed=await api('order',{request_key:key,table_id:table,note,items:cart});draft([],table,'');setEditingDraftIndex(null);setServiceMode('overview');setMessage('Bestellung '+orderNumber(Number(placed.id))+' für '+selectedTable.name+' gesendet.');await refresh();})}>{busy?'Wird gesendet …':'Bestellung für '+selectedTable.name+' senden →'}</button>
   <small>Speisen an die Küche · Getränke an den Tresen</small>
  </section></div>:serviceMode==='payment'&&currentTable?cashier():serviceMode==='overview'&&currentTable?<div className="service-choice"><h2>{currentTable.name}</h2><p>{statusByTable.has(Number(currentTable.id))?'Wähle den nächsten Schritt für diesen Tisch.':'Für diesen Tisch ist noch keine Rechnung offen.'}</p><div><button disabled={!selectedTable} onClick={()=>setServiceMode('order')}>Bestellung aufnehmen →</button><button className="ghost" onClick={()=>setServiceMode('payment')}>Rechnung ansehen →</button></div>{!selectedTable&&<small>Dieser Tisch ist deaktiviert; neue Bestellungen sind gesperrt.</small>}</div>:<div className="select-table-empty"><span aria-hidden="true">▦</span><h2>Für welchen Tisch?</h2><p>Wähle zuerst einen Tisch. Danach kannst du eine Bestellung aufnehmen oder die Rechnung ansehen.</p><button onClick={()=>setTableDrawer(true)}>Tische anzeigen →</button></div>}
  {serviceMode==='overview'&&<h2>Laufende Bestellungen</h2>}
  {tableDrawer&&<div className="drawer-backdrop" onMouseDown={e=>{if(e.target===e.currentTarget)setTableDrawer(false)}}><aside className="table-drawer" role="dialog" aria-modal="true" aria-label="Tisch auswählen"><div className="drawer-title"><div><small>SERVICE</small><h2>Tisch auswählen</h2></div><button className="ghost" aria-label="Tischliste schließen" onClick={()=>setTableDrawer(false)}>✕</button></div><p className="muted">Tische mit Handlungsbedarf stehen oben.</p><div className="table-list">{orderedTables.map(t=>{const s=statusByTable.get(Number(t.id));const phase=s?tablePhase(s):null;const paid=payments.paid.some(p=>p.table_id===Number(t.id));return <button disabled={busy} className={(table===Number(t.id)?'selected ':'')+(phase?'table-'+phase.kind:'')} key={t.id} onClick={()=>chooseTable(Number(t.id))}><b>{t.name}</b><small>{phase?phase.label+' · '+phase.detail:paid?'Zahlungsbestätigung vorhanden':Number(t.active)===1?'Frei':'Deaktiviert · Rechnung einsehbar'}</small>{table===Number(t.id)&&<span>Ausgewählt ✓</span>}</button>})}</div>{orderedTables.length===0&&<p>Keine aktiven Tische vorhanden.</p>}</aside></div>}
 </>}
 {view!=='admin'&&(archive?<div className="archive-grid">{shown.length?shown.map(ticket):<p className="empty">Noch keine abgeschlossenen oder stornierten Bons im Archiv.</p>}</div>:(view!=='service'||serviceMode==='overview')?<div className="board">{['new','working','ready'].map(s=><section className="column" key={s}><h3>{labels[s]} <span>{shown.filter(t=>t.status===s).length}</span></h3>{shown.filter(t=>t.status===s).map(ticket)}{!shown.some(t=>t.status===s)&&<p className="empty">Hier ist gerade alles erledigt.</p>}</section>)}</div>:null)}
 {view==='admin'&&<div className="admin-grid">
  <section className="panel"><h2>Mitarbeiter</h2>
   {users.filter(person=>Number(person.active)===1).map(person=><div className="staff-record" key={person.id}>
    <div className="admin-entry"><div><b>{person.name}</b><small>@{person.username} · {person.roles.map(role=>labels[role]).join(', ')}</small></div><div className="staff-actions"><button type="button" className="ghost" disabled={busy} onClick={()=>setStaffEdit({id:Number(person.id),name:person.name,username:person.username,roles:[...person.roles]})}>Bearbeiten</button><button type="button" className="ghost staff-remove" disabled={busy||Number(person.id)===user.id} onClick={()=>changeStaffStatus(person,false)}>Entfernen</button></div></div>
    {staffEdit?.id===Number(person.id)&&<form className="staff-edit" onSubmit={saveStaff}>
     <strong>{person.name} bearbeiten</strong>
     <label>Name<input required maxLength={80} value={staffEdit.name} onChange={e=>setStaffEdit({...staffEdit,name:e.target.value})}/></label>
     <label>Benutzername<input required minLength={3} maxLength={80} pattern="[A-Za-z0-9._-]+" value={staffEdit.username} onChange={e=>setStaffEdit({...staffEdit,username:e.target.value})}/></label>
     <fieldset><legend>Rollen · mehrere auswählbar</legend>{(['service','kitchen','bar','admin'] as Role[]).map(role=><label className="check" key={role}><input type="checkbox" checked={staffEdit.roles.includes(role)} disabled={role==='admin'&&person.id===user.id} onChange={e=>setStaffEdit({...staffEdit,roles:e.target.checked?[...staffEdit.roles,role]:staffEdit.roles.filter(r=>r!==role)})}/>{labels[role]}</label>)}</fieldset>
     <div className="row"><button type="button" className="ghost" disabled={busy} onClick={()=>setStaffEdit(null)}>Abbrechen</button><button type="submit" disabled={busy||staffEdit.roles.length===0}>Änderungen speichern</button></div>
    </form>}
   </div>)}
   {users.some(person=>Number(person.active)!==1)&&<details className="removed-staff"><summary>Entfernte Mitarbeiter ({users.filter(person=>Number(person.active)!==1).length})</summary>{users.filter(person=>Number(person.active)!==1).map(person=><div className="admin-entry" key={person.id}><div><b>{person.name}</b><small>@{person.username} · {person.roles.map(role=>labels[role]).join(', ')}</small></div><button type="button" className="ghost" disabled={busy} onClick={()=>changeStaffStatus(person,true)}>Wieder aktivieren</button></div>)}</details>}
   <h3>Zugang anlegen</h3>
   <form onSubmit={e=>{e.preventDefault();const form=e.currentTarget;const f=new FormData(form);run(async()=>{await api('admin_user',{name:f.get('name'),username:f.get('username'),password:f.get('password'),roles:f.getAll('roles')});setUsers(await api('admin_users'));form.reset();setMessage('Mitarbeiter angelegt.');});}}>
    <input name="name" placeholder="Name" aria-label="Name" required/><input name="username" placeholder="Benutzername" aria-label="Benutzername" required/><input name="password" type="password" placeholder="Passwort (mind. 12 Zeichen)" aria-label="Neues Passwort" minLength={12} required/>
    <fieldset><legend>Rollen · mehrere auswählbar</legend>{(['service','kitchen','bar','admin'] as Role[]).map(role=><label className="check" key={role}><input type="checkbox" name="roles" value={role}/>{labels[role]}</label>)}</fieldset>
    <button disabled={busy}>Mitarbeiter anlegen</button>
   </form>
  </section>
  <section className="panel"><h2>Speisekarte</h2><div className="categories">{([['bar','Getränke'],['kitchen','Speisen']] as const).map(([group,label])=><button type="button" className={adminMenuGroup===group?'':'ghost'} aria-pressed={adminMenuGroup===group} onClick={()=>{setAdminMenuGroup(group);setMenuEdit(null);setDrinkEdit(null)}} key={group}>{label}</button>)}</div>
   <datalist id={'categories-'+adminMenuGroup}>{[...new Set(menu.filter(m=>m.station===adminMenuGroup).map(m=>m.category))].map(c=><option key={c} value={c}/>)}</datalist>
   {adminMenuGroup==='bar'?<>
   {groupBySize(menu.filter(m=>m.station==='bar')).map(g=>{const available=g.items.filter(m=>Number(m.active)===1);return <div className="staff-record" key={g.name}>
    <div className="admin-entry"><div><b>{g.name}</b><small>{g.items.map(m=>{const ml=sizeKey(m.name)[1];return (ml?ml+' ml · ':'ohne Menge · ')+money(Number(m.price))+(Number(m.active)===1?'':' (nicht verfügbar)');}).join(' | ')}</small><small>{g.items[0].category}{Number(g.items[0].straw)===1?' · Strohhalm-Option':''} · {available.length===g.items.length?'Verfügbar':available.length?'Teilweise verfügbar':'Nicht verfügbar'}</small></div><div className="staff-actions"><button type="button" className="ghost" disabled={busy} onClick={()=>setDrinkEdit({key:g.name,name:g.name,category:g.items[0].category,straw:Number(g.items[0].straw)===1,sizes:g.items.map(m=>{const ml=sizeKey(m.name)[1];return {id:Number(m.id),volume:ml?String(ml):'',price:(Number(m.price)/100).toFixed(2),active:Number(m.active)===1};})})}>Bearbeiten</button><button type="button" className={available.length?'ghost':''} disabled={busy} onClick={()=>run(async()=>{for(const m of g.items)await api('admin_menu_status',{id:Number(m.id),active:!available.length});await catalog();setMessage('Getränkestatus aktualisiert.');})}>{available.length?'Deaktivieren':'Aktivieren'}</button></div></div>
    {drinkEdit?.key===g.name&&drinkForm(drinkEdit)}
   </div>;})}
   <h3>Getränk hinzufügen</h3>
   {drinkEdit?.key==='new'?drinkForm(drinkEdit):<button type="button" disabled={busy} onClick={()=>setDrinkEdit({key:'new',name:'',category:'',straw:false,sizes:[{volume:'',price:'',active:true}]})}>Neues Getränk anlegen</button>}
   </>:<>
   {menu.filter(m=>m.station==='kitchen').sort(byNameAndSize).map(m=><div className="staff-record" key={m.id}>
    <div className="admin-entry"><div><b>{m.name}</b><small>{money(Number(m.price))} · {m.category} · {Number(m.active)===1?'Verfügbar':'Nicht verfügbar'}</small></div><div className="staff-actions"><button type="button" className="ghost" disabled={busy} onClick={()=>setMenuEdit({id:Number(m.id),name:m.name,category:m.category,price:(Number(m.price)/100).toFixed(2)})}>Bearbeiten</button><button type="button" className={Number(m.active)===1?'ghost':''} disabled={busy} onClick={()=>run(async()=>{await api('admin_menu_status',{id:Number(m.id),active:Number(m.active)!==1});await catalog();setMessage('Produktstatus aktualisiert.');})}>{Number(m.active)===1?'Deaktivieren':'Aktivieren'}</button></div></div>
    {menuEdit?.id===Number(m.id)&&<form className="staff-edit" onSubmit={e=>{e.preventDefault();const edit=menuEdit;run(async()=>{await api('admin_menu',{id:edit.id,name:edit.name,category:edit.category,station:'kitchen',price:Math.round(Number(edit.price)*100)});await catalog();setMenuEdit(null);setMessage('Gericht gespeichert. Bereits gesendete Bestellungen behalten Name und Preis.');});}}>
     <strong>{m.name} bearbeiten</strong>
     <label>Name<input required maxLength={120} value={menuEdit.name} onChange={e=>setMenuEdit({...menuEdit,name:e.target.value})}/></label>
     <label>Preis in Euro<input required type="number" min="0" step="0.01" value={menuEdit.price} onChange={e=>setMenuEdit({...menuEdit,price:e.target.value})}/></label>
     <label>Kategorie<input required maxLength={40} list="categories-kitchen" value={menuEdit.category} onChange={e=>setMenuEdit({...menuEdit,category:e.target.value})}/></label>
     <div className="row"><button type="button" className="ghost" disabled={busy} onClick={()=>setMenuEdit(null)}>Abbrechen</button><button type="submit" disabled={busy}>Änderungen speichern</button></div>
    </form>}
   </div>)}
   <h3>Gericht hinzufügen</h3>
   <form onSubmit={e=>{e.preventDefault();const form=e.currentTarget;const f=new FormData(form);run(async()=>{await api('admin_menu',{name:f.get('name'),category:f.get('category'),station:'kitchen',price:Math.round(Number(f.get('price'))*100)});await catalog();form.reset();setMessage('Gericht angelegt.');});}}>
    <input name="name" placeholder="Gerichtname" aria-label="Gerichtname" required/>
    <input name="category" list="categories-kitchen" placeholder="Kategorie" aria-label="Kategorie" required/>
    <input name="price" type="number" min="0" step="0.01" placeholder="Preis in Euro" aria-label="Preis in Euro" required/>
    <button disabled={busy}>Gericht anlegen</button>
   </form></>}</section><section className="panel"><h2>Tische</h2>{tables.map(t=><div className="admin-entry" key={t.id}><div><b>{t.name}</b><small>Nr. {t.id} · {Number(t.active)===1?'Aktiv':'Deaktiviert'}</small></div><button className={Number(t.active)===1?'ghost':''} disabled={busy} onClick={()=>run(async()=>{await api('admin_table_status',{id:Number(t.id),active:Number(t.active)!==1});await catalog();setMessage('Tischstatus aktualisiert.');})}>{Number(t.active)===1?'Deaktivieren':'Aktivieren'}</button></div>)}<h3>Tisch hinzufügen oder umbenennen</h3><form onSubmit={e=>{e.preventDefault();const f=new FormData(e.currentTarget);run(async()=>{await api('admin_table',{id:Number(f.get('id')),name:f.get('name')});await catalog();setMessage('Tisch gespeichert.');});}}><input name="id" type="number" min="1" max="999" placeholder="Tischnummer" aria-label="Tischnummer" required/><input name="name" placeholder="Tischname" aria-label="Tischname" required/><button disabled={busy}>Tisch speichern</button></form><p className="muted">Bestehende Tischnummern werden umbenannt.</p></section></div>}
 </main><footer>Zum Stimbeck · Kitchen Manager <span>Lokale Entwicklungsversion</span></footer></>;
}
createRoot(document.getElementById('root')!).render(<App/>);
